def solve(inputs):
    from functools import reduce
    def extended_gcd(a, b):
        if a == 0:
            return (b, 0, 1)
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a, m)
        if gcd != 1:
            raise Exception('Mod inverse does not exist')
        else:
            return x % m

    def chinese_remainder_theorem(congruences):
        total_sum = 0
        prod = reduce(lambda a, b: a * b, [m for _, m in congruences])

        for a, m in congruences:
            p = prod // m
            total_sum += a * mod_inverse(p, m) * p

        return total_sum % prod

    congruences = [(877, 2243), (444, 937), (787, 1999), (495, 521), (1471, 1997)]
    return chinese_remainder_theorem(congruences)

